use std::collections::{HashMap, HashSet};

use crate::tenants::CompiledTenantModel;

use super::model::{CompiledAuthzModel, CompiledTemplate};

impl CompiledAuthzModel {
    pub fn feldera_sql(&self, pipeline_prefix: &str, tenants: &CompiledTenantModel) -> String {
        let pipeline_name = format!("{pipeline_prefix}_authz");
        let mut lines = vec![
            format!("-- pipeline: {pipeline_name}"),
            "-- generated by conclave-server".to_owned(),
            "".to_owned(),
            "CREATE TABLE compiled_authz_metadata (".to_owned(),
            "  catalog_revision INT NOT NULL,".to_owned(),
            "  policy_revision BIGINT NOT NULL".to_owned(),
            ");".to_owned(),
            "".to_owned(),
            "CREATE TABLE action_catalog (".to_owned(),
            "  revision INT NOT NULL,".to_owned(),
            "  action_name STRING NOT NULL,".to_owned(),
            "  namespace STRING NOT NULL,".to_owned(),
            "  bit_index INT NOT NULL,".to_owned(),
            "  description STRING".to_owned(),
            ");".to_owned(),
            "".to_owned(),
            "CREATE TABLE managed_role_templates (".to_owned(),
            "  tenant_id STRING NOT NULL,".to_owned(),
            "  template_key STRING NOT NULL,".to_owned(),
            "  template_revision BIGINT NOT NULL,".to_owned(),
            "  sync_mode STRING NOT NULL,".to_owned(),
            "  source_tenant STRING,".to_owned(),
            "  source_key STRING,".to_owned(),
            "  source_pin STRING".to_owned(),
            ");".to_owned(),
            "".to_owned(),
            "CREATE TABLE template_policy_overrides (".to_owned(),
            "  tenant_id STRING NOT NULL,".to_owned(),
            "  template_key STRING NOT NULL,".to_owned(),
            "  effect STRING NOT NULL,".to_owned(),
            "  selector STRING NOT NULL,".to_owned(),
            "  bits_hex STRING NOT NULL,".to_owned(),
            "  scope_kind STRING,".to_owned(),
            "  scope_id STRING".to_owned(),
            ");".to_owned(),
            "".to_owned(),
            "CREATE TABLE resolved_template_metadata (".to_owned(),
            "  tenant_id STRING NOT NULL,".to_owned(),
            "  template_key STRING NOT NULL,".to_owned(),
            "  template_revision BIGINT NOT NULL,".to_owned(),
            "  sync_mode STRING NOT NULL,".to_owned(),
            "  source_tenant STRING,".to_owned(),
            "  source_key STRING,".to_owned(),
            "  source_pin STRING,".to_owned(),
            "  source_revision BIGINT".to_owned(),
            ");".to_owned(),
            "".to_owned(),
            "CREATE TABLE template_lineage (".to_owned(),
            "  tenant_id STRING NOT NULL,".to_owned(),
            "  template_key STRING NOT NULL,".to_owned(),
            "  ancestor_tenant_id STRING NOT NULL,".to_owned(),
            "  ancestor_template_key STRING NOT NULL,".to_owned(),
            "  lineage_order INT NOT NULL".to_owned(),
            ");".to_owned(),
            "".to_owned(),
            "CREATE MATERIALIZED VIEW compiled_template_policy_candidates AS".to_owned(),
            "SELECT".to_owned(),
            "  lineage.tenant_id,".to_owned(),
            "  lineage.template_key,".to_owned(),
            "  lineage.lineage_order,".to_owned(),
            "  policies.effect,".to_owned(),
            "  policies.selector,".to_owned(),
            "  policies.bits_hex,".to_owned(),
            "  COALESCE(policies.scope_kind, '') AS scope_kind,".to_owned(),
            "  COALESCE(policies.scope_id, '') AS scope_id".to_owned(),
            "FROM template_lineage AS lineage".to_owned(),
            "JOIN template_policy_overrides AS policies".to_owned(),
            "  ON policies.tenant_id = lineage.ancestor_tenant_id".to_owned(),
            " AND policies.template_key = lineage.ancestor_template_key;".to_owned(),
            "".to_owned(),
            "CREATE MATERIALIZED VIEW compiled_template_policy_max_order AS".to_owned(),
            "SELECT".to_owned(),
            "  tenant_id,".to_owned(),
            "  template_key,".to_owned(),
            "  selector,".to_owned(),
            "  scope_kind,".to_owned(),
            "  scope_id,".to_owned(),
            "  MAX(lineage_order) AS lineage_order".to_owned(),
            "FROM compiled_template_policy_candidates".to_owned(),
            "GROUP BY tenant_id, template_key, selector, scope_kind, scope_id;".to_owned(),
            "".to_owned(),
            "CREATE MATERIALIZED VIEW compiled_template_policies AS".to_owned(),
            "SELECT".to_owned(),
            "  candidates.tenant_id,".to_owned(),
            "  candidates.template_key,".to_owned(),
            "  candidates.effect,".to_owned(),
            "  candidates.selector,".to_owned(),
            "  candidates.bits_hex,".to_owned(),
            "  candidates.scope_kind,".to_owned(),
            "  candidates.scope_id".to_owned(),
            "FROM compiled_template_policy_candidates AS candidates".to_owned(),
            "JOIN compiled_template_policy_max_order AS max_order".to_owned(),
            "  ON max_order.tenant_id = candidates.tenant_id".to_owned(),
            " AND max_order.template_key = candidates.template_key".to_owned(),
            " AND max_order.selector = candidates.selector".to_owned(),
            " AND max_order.scope_kind = candidates.scope_kind".to_owned(),
            " AND max_order.scope_id = candidates.scope_id".to_owned(),
            " AND max_order.lineage_order = candidates.lineage_order;".to_owned(),
            "".to_owned(),
            "CREATE TABLE managed_roles (".to_owned(),
            "  tenant_id STRING NOT NULL,".to_owned(),
            "  role_key STRING NOT NULL,".to_owned(),
            "  role_revision BIGINT NOT NULL,".to_owned(),
            "  template_key STRING,".to_owned(),
            "  inherits_json STRING NOT NULL".to_owned(),
            ");".to_owned(),
            "".to_owned(),
            "CREATE TABLE role_inheritance_edges (".to_owned(),
            "  tenant_id STRING NOT NULL,".to_owned(),
            "  role_key STRING NOT NULL,".to_owned(),
            "  parent_role_key STRING NOT NULL,".to_owned(),
            "  inheritance_order INT NOT NULL".to_owned(),
            ");".to_owned(),
            "".to_owned(),
            "CREATE TABLE role_policy_overrides (".to_owned(),
            "  tenant_id STRING NOT NULL,".to_owned(),
            "  role_key STRING NOT NULL,".to_owned(),
            "  effect STRING NOT NULL,".to_owned(),
            "  selector STRING NOT NULL,".to_owned(),
            "  bits_hex STRING NOT NULL,".to_owned(),
            "  scope_kind STRING,".to_owned(),
            "  scope_id STRING".to_owned(),
            ");".to_owned(),
            "".to_owned(),
            "CREATE TABLE compiled_role_policies (".to_owned(),
            "  tenant_id STRING NOT NULL,".to_owned(),
            "  role_key STRING NOT NULL,".to_owned(),
            "  effect STRING NOT NULL,".to_owned(),
            "  selector STRING NOT NULL,".to_owned(),
            "  bits_hex STRING NOT NULL,".to_owned(),
            "  scope_kind STRING,".to_owned(),
            "  scope_id STRING".to_owned(),
            ");".to_owned(),
            "".to_owned(),
            "CREATE MATERIALIZED VIEW compiled_role_unscoped AS".to_owned(),
            "SELECT tenant_id, role_key, effect, bits_hex".to_owned(),
            "FROM compiled_role_policies".to_owned(),
            "WHERE scope_kind IS NULL;".to_owned(),
            "".to_owned(),
            "CREATE MATERIALIZED VIEW compiled_role_action_effects AS".to_owned(),
            "SELECT".to_owned(),
            "  policies.tenant_id,".to_owned(),
            "  policies.role_key,".to_owned(),
            "  COALESCE(policies.scope_kind, '') AS scope_kind,".to_owned(),
            "  COALESCE(policies.scope_id, '') AS scope_id,".to_owned(),
            "  catalog.action_name,".to_owned(),
            "  catalog.bit_index,".to_owned(),
            "  policies.effect".to_owned(),
            "FROM compiled_role_policies AS policies".to_owned(),
            "JOIN action_catalog AS catalog".to_owned(),
            "  ON catalog.action_name LIKE REPLACE(policies.selector, '*', '%');".to_owned(),
            "".to_owned(),
            "CREATE TABLE effective_grant_identity (".to_owned(),
            "  grant_kind STRING NOT NULL,".to_owned(),
            "  subject_id STRING NOT NULL,".to_owned(),
            "  source_tenant_id STRING NOT NULL,".to_owned(),
            "  source_tenant_state STRING NOT NULL,".to_owned(),
            "  target_tenant_id STRING NOT NULL,".to_owned(),
            "  target_tenant_state STRING NOT NULL,".to_owned(),
            "  facts_json STRING NOT NULL,".to_owned(),
            "  ttl_seconds BIGINT".to_owned(),
            ");".to_owned(),
            "".to_owned(),
            "CREATE TABLE effective_grant_role_assignment (".to_owned(),
            "  grant_kind STRING NOT NULL,".to_owned(),
            "  subject_id STRING NOT NULL,".to_owned(),
            "  source_tenant_id STRING NOT NULL,".to_owned(),
            "  target_tenant_id STRING NOT NULL,".to_owned(),
            "  role_key STRING NOT NULL,".to_owned(),
            "  assignment_order INT NOT NULL,".to_owned(),
            ");".to_owned(),
            "".to_owned(),
            "CREATE MATERIALIZED VIEW effective_grants AS".to_owned(),
            "SELECT".to_owned(),
            "  grant_kind,".to_owned(),
            "  subject_id,".to_owned(),
            "  source_tenant_id,".to_owned(),
            "  source_tenant_state,".to_owned(),
            "  target_tenant_id,".to_owned(),
            "  target_tenant_state,".to_owned(),
            "  facts_json,".to_owned(),
            "  ttl_seconds".to_owned(),
            "FROM effective_grant_identity;".to_owned(),
            "".to_owned(),
            "CREATE MATERIALIZED VIEW effective_grant_action_candidates AS".to_owned(),
            "SELECT".to_owned(),
            "  assignment.grant_kind,".to_owned(),
            "  assignment.subject_id,".to_owned(),
            "  assignment.source_tenant_id,".to_owned(),
            "  assignment.target_tenant_id,".to_owned(),
            "  effects.scope_kind,".to_owned(),
            "  effects.scope_id,".to_owned(),
            "  effects.action_name,".to_owned(),
            "  effects.bit_index,".to_owned(),
            "  effects.effect,".to_owned(),
            "  assignment.assignment_order".to_owned(),
            "FROM effective_grant_role_assignment AS assignment".to_owned(),
            "JOIN compiled_role_action_effects AS effects".to_owned(),
            "  ON effects.tenant_id = assignment.target_tenant_id".to_owned(),
            " AND effects.role_key = assignment.role_key;".to_owned(),
            "".to_owned(),
            "CREATE MATERIALIZED VIEW effective_grant_action_max_order AS".to_owned(),
            "SELECT".to_owned(),
            "  grant_kind,".to_owned(),
            "  subject_id,".to_owned(),
            "  source_tenant_id,".to_owned(),
            "  target_tenant_id,".to_owned(),
            "  scope_kind,".to_owned(),
            "  scope_id,".to_owned(),
            "  action_name,".to_owned(),
            "  MAX(assignment_order) AS assignment_order".to_owned(),
            "FROM effective_grant_action_candidates".to_owned(),
            "GROUP BY".to_owned(),
            "  grant_kind,".to_owned(),
            "  subject_id,".to_owned(),
            "  source_tenant_id,".to_owned(),
            "  target_tenant_id,".to_owned(),
            "  scope_kind,".to_owned(),
            "  scope_id,".to_owned(),
            "  action_name;".to_owned(),
            "".to_owned(),
            "CREATE MATERIALIZED VIEW effective_grant_action_precedence AS".to_owned(),
            "SELECT".to_owned(),
            "  candidates.grant_kind,".to_owned(),
            "  candidates.subject_id,".to_owned(),
            "  candidates.source_tenant_id,".to_owned(),
            "  candidates.target_tenant_id,".to_owned(),
            "  candidates.scope_kind,".to_owned(),
            "  candidates.scope_id,".to_owned(),
            "  candidates.action_name,".to_owned(),
            "  MAX(CASE WHEN candidates.effect = 'deny' THEN 1 ELSE 0 END) AS effect_rank"
                .to_owned(),
            "FROM effective_grant_action_candidates AS candidates".to_owned(),
            "JOIN effective_grant_action_max_order AS max_order".to_owned(),
            "  ON max_order.grant_kind = candidates.grant_kind".to_owned(),
            " AND max_order.subject_id = candidates.subject_id".to_owned(),
            " AND max_order.source_tenant_id = candidates.source_tenant_id".to_owned(),
            " AND max_order.target_tenant_id = candidates.target_tenant_id".to_owned(),
            " AND max_order.scope_kind = candidates.scope_kind".to_owned(),
            " AND max_order.scope_id = candidates.scope_id".to_owned(),
            " AND max_order.action_name = candidates.action_name".to_owned(),
            " AND max_order.assignment_order = candidates.assignment_order".to_owned(),
            "GROUP BY".to_owned(),
            "  candidates.grant_kind,".to_owned(),
            "  candidates.subject_id,".to_owned(),
            "  candidates.source_tenant_id,".to_owned(),
            "  candidates.target_tenant_id,".to_owned(),
            "  candidates.scope_kind,".to_owned(),
            "  candidates.scope_id,".to_owned(),
            "  candidates.action_name;".to_owned(),
            "".to_owned(),
            "CREATE MATERIALIZED VIEW effective_grant_actions AS".to_owned(),
            "SELECT".to_owned(),
            "  candidates.grant_kind,".to_owned(),
            "  candidates.subject_id,".to_owned(),
            "  candidates.source_tenant_id,".to_owned(),
            "  candidates.target_tenant_id,".to_owned(),
            "  candidates.scope_kind,".to_owned(),
            "  candidates.scope_id,".to_owned(),
            "  candidates.action_name,".to_owned(),
            "  candidates.bit_index".to_owned(),
            "FROM effective_grant_action_candidates AS candidates".to_owned(),
            "JOIN effective_grant_action_max_order AS max_order".to_owned(),
            "  ON max_order.grant_kind = candidates.grant_kind".to_owned(),
            " AND max_order.subject_id = candidates.subject_id".to_owned(),
            " AND max_order.source_tenant_id = candidates.source_tenant_id".to_owned(),
            " AND max_order.target_tenant_id = candidates.target_tenant_id".to_owned(),
            " AND max_order.scope_kind = candidates.scope_kind".to_owned(),
            " AND max_order.scope_id = candidates.scope_id".to_owned(),
            " AND max_order.action_name = candidates.action_name".to_owned(),
            " AND max_order.assignment_order = candidates.assignment_order".to_owned(),
            "JOIN effective_grant_action_precedence AS precedence".to_owned(),
            "  ON precedence.grant_kind = candidates.grant_kind".to_owned(),
            " AND precedence.subject_id = candidates.subject_id".to_owned(),
            " AND precedence.source_tenant_id = candidates.source_tenant_id".to_owned(),
            " AND precedence.target_tenant_id = candidates.target_tenant_id".to_owned(),
            " AND precedence.scope_kind = candidates.scope_kind".to_owned(),
            " AND precedence.scope_id = candidates.scope_id".to_owned(),
            " AND precedence.action_name = candidates.action_name".to_owned(),
            "WHERE candidates.effect = 'allow'".to_owned(),
            "  AND (CASE WHEN candidates.effect = 'deny' THEN 1 ELSE 0 END) = precedence.effect_rank;"
                .to_owned(),
            "".to_owned(),
        ];

        lines.push(format!(
            "INSERT INTO compiled_authz_metadata VALUES ({}, {});",
            self.catalog_revision, tenants.policy_revision
        ));
        lines.push(String::new());

        for action in &self.actions {
            lines.push(format!(
                "INSERT INTO action_catalog VALUES ({}, '{}', '{}', {}, {});",
                self.catalog_revision,
                sql_escape(&action.name),
                sql_escape(&action.namespace),
                action.bit,
                action
                    .description
                    .as_deref()
                    .map(|value| format!("'{}'", sql_escape(value)))
                    .unwrap_or_else(|| "NULL".to_owned())
            ));
        }

        lines.push(String::new());

        for template in &self.templates {
            let (source_tenant, source_key, source_pin) = template
                .source
                .as_ref()
                .map(|source| {
                    (
                        format!("'{}'", sql_escape(&source.tenant)),
                        format!("'{}'", sql_escape(&source.key)),
                        source
                            .pin
                            .as_deref()
                            .map(|value| format!("'{}'", sql_escape(value)))
                            .unwrap_or_else(|| "NULL".to_owned()),
                    )
                })
                .unwrap_or_else(|| ("NULL".to_owned(), "NULL".to_owned(), "NULL".to_owned()));

            lines.push(format!(
                "INSERT INTO managed_role_templates VALUES ('{}', '{}', {}, '{}', {}, {}, {});",
                sql_escape(&template.tenant),
                sql_escape(&template.key),
                template.revision,
                sql_escape(&template.sync_mode),
                source_tenant,
                source_key,
                source_pin,
            ));

            for policy in &template.local_policies {
                let scope_kind = policy
                    .scope_kind
                    .as_deref()
                    .map(|value| format!("'{}'", sql_escape(value)))
                    .unwrap_or_else(|| "NULL".to_owned());
                let scope_id = policy
                    .scope_id
                    .as_deref()
                    .map(|value| format!("'{}'", sql_escape(value)))
                    .unwrap_or_else(|| "NULL".to_owned());

                lines.push(format!(
                    "INSERT INTO template_policy_overrides VALUES ('{}', '{}', '{}', '{}', '{}', {}, {});",
                    sql_escape(&template.tenant),
                    sql_escape(&template.key),
                    sql_escape(&policy.effect),
                    sql_escape(&policy.selector),
                    sql_escape(&policy.bits_hex),
                    scope_kind,
                    scope_id
                ));
            }
        }

        lines.push(String::new());
        for template in ordered_templates_for_sql(self) {
            lines.extend(template_resolution_sql(template));
        }

        lines.push(String::new());

        for role in &self.roles {
            let template_key = role
                .template
                .as_deref()
                .map(|value| format!("'{}'", sql_escape(value)))
                .unwrap_or_else(|| "NULL".to_owned());
            let inherits_json = format!(
                "'{}'",
                sql_escape(
                    &serde_json::to_string(&role.inherits)
                        .expect("compiled role inheritance should serialize",)
                )
            );

            lines.push(format!(
                "INSERT INTO managed_roles VALUES ('{}', '{}', {}, {}, {});",
                sql_escape(&role.tenant),
                sql_escape(&role.key),
                role.revision,
                template_key,
                inherits_json
            ));

            for (inheritance_order, parent_role_key) in role.inherits.iter().enumerate() {
                lines.push(format!(
                    "INSERT INTO role_inheritance_edges VALUES ('{}', '{}', '{}', {});",
                    sql_escape(&role.tenant),
                    sql_escape(&role.key),
                    sql_escape(parent_role_key),
                    inheritance_order,
                ));
            }

            for policy in &role.local_policies {
                let scope_kind = policy
                    .scope_kind
                    .as_deref()
                    .map(|value| format!("'{}'", sql_escape(value)))
                    .unwrap_or_else(|| "NULL".to_owned());
                let scope_id = policy
                    .scope_id
                    .as_deref()
                    .map(|value| format!("'{}'", sql_escape(value)))
                    .unwrap_or_else(|| "NULL".to_owned());

                lines.push(format!(
                    "INSERT INTO role_policy_overrides VALUES ('{}', '{}', '{}', '{}', '{}', {}, {});",
                    sql_escape(&role.tenant),
                    sql_escape(&role.key),
                    sql_escape(&policy.effect),
                    sql_escape(&policy.selector),
                    sql_escape(&policy.bits_hex),
                    scope_kind,
                    scope_id
                ));
            }
        }

        lines.push(String::new());
        for role in ordered_roles_for_sql(self) {
            lines.extend(role_resolution_sql(role));
        }

        lines.push(String::new());

        for membership in &tenants.memberships {
            let target_tenant_state = tenants
                .tenants
                .iter()
                .find(|tenant| tenant.id == membership.tenant)
                .map(|tenant| tenant.state.as_str())
                .expect("membership tenant should exist");
            let facts_json = sql_escape(
                &serde_json::to_string(&membership.facts)
                    .expect("membership facts should serialize"),
            );

            for (assignment_order, role_key) in membership.role_keys.iter().enumerate() {
                lines.push(format!(
                    "INSERT INTO effective_grant_role_assignment VALUES ('direct', '{}', '', '{}', '{}', {});",
                    sql_escape(&membership.subject),
                    sql_escape(&membership.tenant),
                    sql_escape(role_key),
                    assignment_order,
                ));
            }

            lines.push(format!(
                "INSERT INTO effective_grant_identity VALUES ('direct', '{}', '', '', '{}', '{}', '{}', NULL);",
                sql_escape(&membership.subject),
                sql_escape(&membership.tenant),
                sql_escape(target_tenant_state),
                facts_json,
            ));
        }

        for grant in &tenants.assumption_grants {
            let source_tenant_state = tenants
                .tenants
                .iter()
                .find(|tenant| tenant.id == grant.source_tenant)
                .map(|tenant| tenant.state.as_str())
                .expect("assumption source tenant should exist");
            let target_tenant_state = tenants
                .tenants
                .iter()
                .find(|tenant| tenant.id == grant.target_tenant)
                .map(|tenant| tenant.state.as_str())
                .expect("assumption target tenant should exist");
            let source_facts_json = tenants
                .memberships
                .iter()
                .find(|membership| {
                    membership.subject == grant.subject && membership.tenant == grant.source_tenant
                })
                .map(|membership| {
                    serde_json::to_string(&membership.facts)
                        .expect("assumption source facts should serialize")
                })
                .expect("assumption source membership should exist");
            let facts_json = sql_escape(&source_facts_json);

            for (assignment_order, role_key) in grant.target_role_keys.iter().enumerate() {
                lines.push(format!(
                    "INSERT INTO effective_grant_role_assignment VALUES ('assumed', '{}', '{}', '{}', '{}', {});",
                    sql_escape(&grant.subject),
                    sql_escape(&grant.source_tenant),
                    sql_escape(&grant.target_tenant),
                    sql_escape(role_key),
                    assignment_order,
                ));
            }

            lines.push(format!(
                "INSERT INTO effective_grant_identity VALUES ('assumed', '{}', '{}', '{}', '{}', '{}', '{}', {});",
                sql_escape(&grant.subject),
                sql_escape(&grant.source_tenant),
                sql_escape(source_tenant_state),
                sql_escape(&grant.target_tenant),
                sql_escape(target_tenant_state),
                facts_json,
                grant.ttl_seconds,
            ));
        }

        lines.join("\n")
    }
}

fn ordered_templates_for_sql<'a>(authz: &'a CompiledAuthzModel) -> Vec<&'a CompiledTemplate> {
    let by_identity = authz
        .templates
        .iter()
        .map(|template| (template_sql_identity(template), template))
        .collect::<HashMap<_, _>>();
    let mut ordered = Vec::with_capacity(authz.templates.len());
    let mut visited = HashSet::new();

    for template in &authz.templates {
        visit_template_for_sql(template, &by_identity, &mut visited, &mut ordered);
    }

    ordered
}

fn visit_template_for_sql<'a>(
    template: &'a CompiledTemplate,
    by_identity: &HashMap<String, &'a CompiledTemplate>,
    visited: &mut HashSet<String>,
    ordered: &mut Vec<&'a CompiledTemplate>,
) {
    let identity = template_sql_identity(template);
    if !visited.insert(identity) {
        return;
    }

    if let Some(source) = template.source.as_ref() {
        if let Some(parent) = by_identity.get(&format!("{}:{}", source.tenant, source.key)) {
            visit_template_for_sql(parent, by_identity, visited, ordered);
        }
    }

    ordered.push(template);
}

fn template_resolution_sql(template: &CompiledTemplate) -> Vec<String> {
    let tenant = sql_escape(&template.tenant);
    let key = sql_escape(&template.key);

    match template.source.as_ref() {
        Some(source) => {
            let source_tenant = sql_escape(&source.tenant);
            let source_key = sql_escape(&source.key);
            let source_pin = source
                .pin
                .as_deref()
                .map(sql_escape)
                .map(|value| format!("'{value}'"))
                .unwrap_or_else(|| "NULL".to_owned());
            let source_revision = if source.mode == "pinned" {
                source
                    .pin
                    .as_deref()
                    .and_then(|value| value.parse::<u64>().ok())
                    .map(|value| value.to_string())
                    .unwrap_or_else(|| "NULL".to_owned())
            } else {
                "parent.template_revision".to_owned()
            };

            vec![
                format!(
                    "INSERT INTO resolved_template_metadata SELECT '{tenant}', '{key}', {}, '{}', '{}', '{}', {}, {} \
FROM resolved_template_metadata AS parent \
WHERE parent.tenant_id = '{}' AND parent.template_key = '{}';",
                    template.revision,
                    sql_escape(&template.sync_mode),
                    source_tenant,
                    source_key,
                    source_pin,
                    source_revision,
                    source_tenant,
                    source_key,
                ),
                format!(
                    "INSERT INTO template_lineage SELECT '{tenant}', '{key}', ancestor_tenant_id, ancestor_template_key, lineage_order \
FROM template_lineage \
WHERE tenant_id = '{}' AND template_key = '{}';",
                    source_tenant,
                    source_key,
                ),
                format!(
                    "INSERT INTO template_lineage SELECT '{tenant}', '{key}', '{tenant}', '{key}', COALESCE(MAX(lineage_order), -1) + 1 \
FROM template_lineage \
WHERE tenant_id = '{}' AND template_key = '{}';",
                    source_tenant,
                    source_key,
                ),
            ]
        }
        None => vec![
            format!(
                "INSERT INTO resolved_template_metadata VALUES ('{tenant}', '{key}', {}, '{}', NULL, NULL, NULL, NULL);",
                template.revision,
                sql_escape(&template.sync_mode),
            ),
            format!(
                "INSERT INTO template_lineage VALUES ('{tenant}', '{key}', '{tenant}', '{key}', 0);"
            ),
        ],
    }
}

fn template_sql_identity(template: &CompiledTemplate) -> String {
    format!("{}:{}", template.tenant, template.key)
}

fn ordered_roles_for_sql<'a>(authz: &'a CompiledAuthzModel) -> Vec<&'a super::model::CompiledRole> {
    let by_identity = authz
        .roles
        .iter()
        .map(|role| (role_sql_identity(role), role))
        .collect::<HashMap<_, _>>();
    let mut ordered = Vec::with_capacity(authz.roles.len());
    let mut visited = HashSet::new();

    for role in &authz.roles {
        visit_role_for_sql(role, &by_identity, &mut visited, &mut ordered);
    }

    ordered
}

fn visit_role_for_sql<'a>(
    role: &'a super::model::CompiledRole,
    by_identity: &HashMap<String, &'a super::model::CompiledRole>,
    visited: &mut HashSet<String>,
    ordered: &mut Vec<&'a super::model::CompiledRole>,
) {
    let identity = role_sql_identity(role);
    if !visited.insert(identity) {
        return;
    }

    for parent in &role.inherits {
        if let Some(parent_role) = by_identity.get(&format!("{}:{parent}", role.tenant)) {
            visit_role_for_sql(parent_role, by_identity, visited, ordered);
        }
    }

    ordered.push(role);
}

fn role_resolution_sql(role: &super::model::CompiledRole) -> Vec<String> {
    let tenant = sql_escape(&role.tenant);
    let key = sql_escape(&role.key);
    let template_candidates = format!(
        "SELECT template.effect, template.selector, template.bits_hex, COALESCE(template.scope_kind, '') AS scope_kind, COALESCE(template.scope_id, '') AS scope_id, \
COALESCE((SELECT MAX(inheritance_order) + 1 FROM role_inheritance_edges WHERE tenant_id = '{tenant}' AND role_key = '{key}'), 0) AS precedence \
FROM managed_roles AS role \
JOIN compiled_template_policies AS template \
  ON template.tenant_id = role.tenant_id \
 AND template.template_key = role.template_key \
WHERE role.tenant_id = '{tenant}' AND role.role_key = '{key}' AND role.template_key IS NOT NULL"
    );
    let local_candidates = format!(
        "SELECT local.effect, local.selector, local.bits_hex, COALESCE(local.scope_kind, '') AS scope_kind, COALESCE(local.scope_id, '') AS scope_id, \
COALESCE((SELECT MAX(inheritance_order) + 1 FROM role_inheritance_edges WHERE tenant_id = '{tenant}' AND role_key = '{key}'), 0) + \
CASE WHEN EXISTS(SELECT 1 FROM managed_roles WHERE tenant_id = '{tenant}' AND role_key = '{key}' AND template_key IS NOT NULL) THEN 1 ELSE 0 END AS precedence \
FROM role_policy_overrides AS local \
WHERE local.tenant_id = '{tenant}' AND local.role_key = '{key}'"
    );
    let inherited_candidates = format!(
        "SELECT inherited.effect, inherited.selector, inherited.bits_hex, COALESCE(inherited.scope_kind, '') AS scope_kind, COALESCE(inherited.scope_id, '') AS scope_id, edges.inheritance_order AS precedence \
FROM role_inheritance_edges AS edges \
JOIN compiled_role_policies AS inherited \
  ON inherited.tenant_id = edges.tenant_id \
 AND inherited.role_key = edges.parent_role_key \
WHERE edges.tenant_id = '{tenant}' AND edges.role_key = '{key}'"
    );
    let candidate_union = format!(
        "{inherited_candidates} UNION ALL {template_candidates} UNION ALL {local_candidates}"
    );

    vec![format!(
        "INSERT INTO compiled_role_policies \
SELECT '{tenant}', '{key}', candidates.effect, candidates.selector, candidates.bits_hex, NULLIF(candidates.scope_kind, ''), NULLIF(candidates.scope_id, '') \
FROM ({candidate_union}) AS candidates \
JOIN (SELECT selector, scope_kind, scope_id, MAX(precedence) AS precedence FROM ({candidate_union}) AS grouped_candidates GROUP BY selector, scope_kind, scope_id) AS max_precedence \
  ON max_precedence.selector = candidates.selector \
 AND max_precedence.scope_kind = candidates.scope_kind \
 AND max_precedence.scope_id = candidates.scope_id \
 AND max_precedence.precedence = candidates.precedence;"
    )]
}

fn role_sql_identity(role: &super::model::CompiledRole) -> String {
    format!("{}:{}", role.tenant, role.key)
}

fn sql_escape(value: &str) -> String {
    value.replace('\'', "''")
}
